DO $guard$ BEGIN
 IF EXISTS(SELECT 1 FROM grammar.content_releases WHERE version='core-2026-09-v3' AND content_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4') THEN RAISE EXCEPTION 'Published release is immutable'; END IF;
 IF EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reported-statements' AND (catalog_hash<>'e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4' OR payload_md5<>'240449ca1b613df5b215f5878410c9f7')) THEN RAISE EXCEPTION 'Catalog payload conflict: use a new version'; END IF;
END $guard$;
INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','reported-statements','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"reported-statements","title":"Reported speech: statements and reference","level":"B1","order":50,"summary":"Report someone’s message while adjusting tense, pronouns and time words to the reporting situation.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Reporting is a change of viewpoint","Backshift after a past reporting verb","Say and tell","Modals and continuing truth"],"rules":[{"title":"Reporting is a change of viewpoint","explanation":"Reported speech conveys a message without quoting the exact words. A that-clause commonly follows said or told. Pronouns and time expressions depend on who reports the message, where and when. Do not change them mechanically without checking the situation.","pattern":"“I’m ready.” → She said **she was ready**.","commonMistakes":["If the report is made on the same day, today may remain today. There is no compulsory word-replacement table independent of context."],"examples":["Backshift this report: She said, “I prepare the visitor guide every week.” → She said she **prepared** the visitor guide every week.","Backshift this report: She said, “I restore the old portrait every week.” → She said she **restored** the old portrait every week."],"skill":"form"},{"title":"Backshift after a past reporting verb","explanation":"When a report looks back from a later time, present often shifts to past, past to past perfect, and will to would. This is called backshift. It helps mark the original message as earlier than the reporting moment.","pattern":"“I work here.” → He said he **worked** there.","commonMistakes":["Backshift is not always necessary if the message is still true or relevant. The exercises explicitly request it where needed."],"examples":["Report the plan with backshift: “I will prepare the visitor guide.” → She said she **would prepare** the visitor guide.","Report the plan with backshift: “I will restore the old portrait.” → She said she **would restore** the old portrait."],"skill":"meaning"},{"title":"Say and tell","explanation":"Use **say something** or **say to someone**. Use **tell someone something** with an object naming the listener. These are different verb patterns. Told me that and said to me that can both be correct.","pattern":"She **told me** the news. / She **said** she was tired.","commonMistakes":["She said me is not the standard pattern; use told me or said to me."],"examples":["Choose the verb pattern: “She **told** me that she would prepare the visitor guide.”","Choose the verb pattern: “She **told** me that she would restore the old portrait.”"],"skill":"contrast"},{"title":"Modals and continuing truth","explanation":"Will commonly becomes would and can becomes could in a backshifted report. Would, could, should and might often remain unchanged. A current fact can remain in present tense when the reporter endorses it as still true.","pattern":"He said the Earth **is** round.","commonMistakes":["Reported speech is about accurate meaning, not changing every verb merely because said is past."],"examples":["Backshift a finished past statement: “We prepared the visitor guide.” → They said they **had prepared** the visitor guide.","Backshift a finished past statement: “We restored the old portrait.” → They said they **had restored** the old portrait."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"08d2afd6-d917-5206-a046-b48a3f0e8603","topicSlug":"reported-statements","level":"B1","prompt":"Backshift this report: She said, “I prepare the visitor guide every week.” → She said she ____ the visitor guide every week.","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepared"},{"id":"D","text":"prepares"}],"answerId":"C","hint":"The reporting verb is past and the instruction requests a **present-to-past backshift**.","explanation":"The instruction requests backshift from present prepare to past **prepared**.","keywords":["present-backshift"],"skill":"present-backshift","contextKey":"reported-statements-1","fingerprint":"ecdfa1d2d5ac1b66aa0a3dc0a5fdad59b07fa637eb626862c0d5efc1ef43ba5c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb is past and the instruction requests a **present-to-past backshift**.","The instruction requests backshift from present prepare to past **prepared**.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form alone does not supply a finite reported verb.","B":"A to-infinitive does not complete this that-clause.","C":"The instruction requests backshift from present prepare to past **prepared**.","D":"This keeps present tense; the task explicitly requests backshift."}}},{"id":"af91dfef-b3a9-581e-a2bd-95009dea778a","topicSlug":"reported-statements","level":"B1","prompt":"Report the plan with backshift: “I will prepare the visitor guide.” → She said she ____ the visitor guide.","choices":[{"id":"A","text":"would prepare"},{"id":"B","text":"would prepared"},{"id":"C","text":"would to prepare"},{"id":"D","text":"will preparing"}],"answerId":"A","hint":"Backshift the **modal**, not the main verb after it.","explanation":"Backshift **will** to **would**, keeping base prepare.","keywords":["future-backshift"],"skill":"future-backshift","contextKey":"reported-statements-1","fingerprint":"b5f44a202cd7919387158652eec31558b2dfd915df3acae9dfef7e6b4d5cba52","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Backshift the **modal**, not the main verb after it.","Backshift **will** to **would**, keeping base prepare.","Choose **would prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Backshift **will** to **would**, keeping base prepare.","B":"The verb after would must remain in its base form.","C":"Would takes a bare infinitive without to.","D":"Will cannot directly take -ing, and it does not perform the requested backshift."}}},{"id":"27e5b754-7983-56ca-ab18-e6f6f212df2b","topicSlug":"reported-statements","level":"B1","prompt":"Choose the verb pattern: “She ____ me that she would prepare the visitor guide.”","choices":[{"id":"A","text":"told"},{"id":"B","text":"said"},{"id":"C","text":"spoke"},{"id":"D","text":"talked"}],"answerId":"A","hint":"The listener **me** follows the reporting verb directly.","explanation":"**Told me that** uses tell with a listener object.","keywords":["tell-object"],"skill":"tell-object","contextKey":"reported-statements-1","fingerprint":"db1ae37a62a6a44135d4520f0c2d35c231b7b3973e3f7f96217a397ce0789be3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The listener **me** follows the reporting verb directly.","**Told me that** uses tell with a listener object.","Choose **told**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Told me that** uses tell with a listener object.","B":"Say does not take me directly in this pattern; it would need to me.","C":"Spoke me that is not the required reporting pattern.","D":"Talked me that is not the standard statement-reporting pattern."}}},{"id":"a7dea9e6-e186-5c37-a50f-ef1e867815f5","topicSlug":"reported-statements","level":"B1","prompt":"Backshift a finished past statement: “We prepared the visitor guide.” → They said they ____ the visitor guide.","choices":[{"id":"A","text":"had to prepare"},{"id":"B","text":"had prepared"},{"id":"C","text":"have prepared"},{"id":"D","text":"had preparing"}],"answerId":"B","hint":"The original action is already past; the requested backshift is **past perfect**.","explanation":"A requested backshift from past simple uses **had + prepared**.","keywords":["past-backshift"],"skill":"past-backshift","contextKey":"reported-statements-1","fingerprint":"f1a35d1bdbe06fc2abb5ae79b511d8f6a6ab5a5fa2e2a48d0426c3c2063beca8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The original action is already past; the requested backshift is **past perfect**.","A requested backshift from past simple uses **had + prepared**.","Choose **had prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had to changes the meaning to obligation rather than reporting the completed action.","B":"A requested backshift from past simple uses **had + prepared**.","C":"Present perfect is not the requested backshift from past simple.","D":"Had needs a past participle in the past perfect."}}},{"id":"c5bc291e-539b-5942-a66d-e69eed594eca","topicSlug":"reported-statements","level":"B1","prompt":"Backshift this report: She said, “I restore the old portrait every week.” → She said she ____ the old portrait every week.","choices":[{"id":"A","text":"restored"},{"id":"B","text":"restores"},{"id":"C","text":"restoring"},{"id":"D","text":"to restore"}],"answerId":"A","hint":"The reporting verb is past and the instruction requests a **present-to-past backshift**.","explanation":"The instruction requests backshift from present restore to past **restored**.","keywords":["present-backshift"],"skill":"present-backshift","contextKey":"reported-statements-2","fingerprint":"69c0eb5e52be3ef4d09e7007ada6347158776efab95aa4001f8b2e7c02da6b5a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb is past and the instruction requests a **present-to-past backshift**.","The instruction requests backshift from present restore to past **restored**.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The instruction requests backshift from present restore to past **restored**.","B":"This keeps present tense; the task explicitly requests backshift.","C":"An -ing form alone does not supply a finite reported verb.","D":"A to-infinitive does not complete this that-clause."}}},{"id":"342dfff6-95e9-5988-acbb-2cce1f5bb8f6","topicSlug":"reported-statements","level":"B1","prompt":"Report the plan with backshift: “I will restore the old portrait.” → She said she ____ the old portrait.","choices":[{"id":"A","text":"would restore"},{"id":"B","text":"would restored"},{"id":"C","text":"would to restore"},{"id":"D","text":"will restoring"}],"answerId":"A","hint":"Backshift the **modal**, not the main verb after it.","explanation":"Backshift **will** to **would**, keeping base restore.","keywords":["future-backshift"],"skill":"future-backshift","contextKey":"reported-statements-2","fingerprint":"4d6adb46a25dbeea17e9c6280eb2faa389536a445e0d448232fdd613b1b2773c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Backshift the **modal**, not the main verb after it.","Backshift **will** to **would**, keeping base restore.","Choose **would restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Backshift **will** to **would**, keeping base restore.","B":"The verb after would must remain in its base form.","C":"Would takes a bare infinitive without to.","D":"Will cannot directly take -ing, and it does not perform the requested backshift."}}},{"id":"774bf964-58be-5f09-afa8-5c84391ef7ce","topicSlug":"reported-statements","level":"B1","prompt":"Choose the verb pattern: “She ____ me that she would restore the old portrait.”","choices":[{"id":"A","text":"told"},{"id":"B","text":"said"},{"id":"C","text":"spoke"},{"id":"D","text":"talked"}],"answerId":"A","hint":"The listener **me** follows the reporting verb directly.","explanation":"**Told me that** uses tell with a listener object.","keywords":["tell-object"],"skill":"tell-object","contextKey":"reported-statements-2","fingerprint":"01306e94b18dde9633593ec35bd5deb136e0e644a990d02eb2a3c67ab25d7c52","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The listener **me** follows the reporting verb directly.","**Told me that** uses tell with a listener object.","Choose **told**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Told me that** uses tell with a listener object.","B":"Say does not take me directly in this pattern; it would need to me.","C":"Spoke me that is not the required reporting pattern.","D":"Talked me that is not the standard statement-reporting pattern."}}},{"id":"b91eecd0-a113-53bc-a148-e11e1841b102","topicSlug":"reported-statements","level":"B1","prompt":"Backshift a finished past statement: “We restored the old portrait.” → They said they ____ the old portrait.","choices":[{"id":"A","text":"had restoring"},{"id":"B","text":"had to restore"},{"id":"C","text":"had restored"},{"id":"D","text":"have restored"}],"answerId":"C","hint":"The original action is already past; the requested backshift is **past perfect**.","explanation":"A requested backshift from past simple uses **had + restored**.","keywords":["past-backshift"],"skill":"past-backshift","contextKey":"reported-statements-2","fingerprint":"d9702c030b99f4f85ed63210198499c2ae229c1bd1a01889f57a8bf20e799eff","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The original action is already past; the requested backshift is **past perfect**.","A requested backshift from past simple uses **had + restored**.","Choose **had restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had needs a past participle in the past perfect.","B":"Had to changes the meaning to obligation rather than reporting the completed action.","C":"A requested backshift from past simple uses **had + restored**.","D":"Present perfect is not the requested backshift from past simple."}}},{"id":"374bf11f-bec9-54fa-ac57-5cd198d49bfb","topicSlug":"reported-statements","level":"B1","prompt":"Backshift this report: She said, “I measure the garden fence every week.” → She said she ____ the garden fence every week.","choices":[{"id":"A","text":"measured"},{"id":"B","text":"measures"},{"id":"C","text":"measuring"},{"id":"D","text":"to measure"}],"answerId":"A","hint":"The reporting verb is past and the instruction requests a **present-to-past backshift**.","explanation":"The instruction requests backshift from present measure to past **measured**.","keywords":["present-backshift"],"skill":"present-backshift","contextKey":"reported-statements-3","fingerprint":"3f7dd95ea2b50d089349ed9a8838b17e7e831a355f873d6b8db9f8c9e31d4f66","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb is past and the instruction requests a **present-to-past backshift**.","The instruction requests backshift from present measure to past **measured**.","Choose **measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The instruction requests backshift from present measure to past **measured**.","B":"This keeps present tense; the task explicitly requests backshift.","C":"An -ing form alone does not supply a finite reported verb.","D":"A to-infinitive does not complete this that-clause."}}},{"id":"6c14d863-c00b-5ea7-aabb-92ec81f28512","topicSlug":"reported-statements","level":"B1","prompt":"Report the plan with backshift: “I will measure the garden fence.” → She said she ____ the garden fence.","choices":[{"id":"A","text":"will measuring"},{"id":"B","text":"would measure"},{"id":"C","text":"would measured"},{"id":"D","text":"would to measure"}],"answerId":"B","hint":"Backshift the **modal**, not the main verb after it.","explanation":"Backshift **will** to **would**, keeping base measure.","keywords":["future-backshift"],"skill":"future-backshift","contextKey":"reported-statements-3","fingerprint":"183ebf4e100e061dd2029d3c1482039d2bce21301a7873cac24b437282837435","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Backshift the **modal**, not the main verb after it.","Backshift **will** to **would**, keeping base measure.","Choose **would measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Will cannot directly take -ing, and it does not perform the requested backshift.","B":"Backshift **will** to **would**, keeping base measure.","C":"The verb after would must remain in its base form.","D":"Would takes a bare infinitive without to."}}},{"id":"07699247-eecc-5685-a63e-6b28281c6e3e","topicSlug":"reported-statements","level":"B1","prompt":"Choose the verb pattern: “She ____ me that she would measure the garden fence.”","choices":[{"id":"A","text":"talked"},{"id":"B","text":"told"},{"id":"C","text":"said"},{"id":"D","text":"spoke"}],"answerId":"B","hint":"The listener **me** follows the reporting verb directly.","explanation":"**Told me that** uses tell with a listener object.","keywords":["tell-object"],"skill":"tell-object","contextKey":"reported-statements-3","fingerprint":"7d51a0a916aab283c5328da2979825bbacb000c7538a930694c2b90342b809fd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The listener **me** follows the reporting verb directly.","**Told me that** uses tell with a listener object.","Choose **told**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Talked me that is not the standard statement-reporting pattern.","B":"**Told me that** uses tell with a listener object.","C":"Say does not take me directly in this pattern; it would need to me.","D":"Spoke me that is not the required reporting pattern."}}},{"id":"90d51958-889a-5abd-a5bc-aaddd0c62a46","topicSlug":"reported-statements","level":"B1","prompt":"Backshift a finished past statement: “We measured the garden fence.” → They said they ____ the garden fence.","choices":[{"id":"A","text":"had to measure"},{"id":"B","text":"had measured"},{"id":"C","text":"have measured"},{"id":"D","text":"had measuring"}],"answerId":"B","hint":"The original action is already past; the requested backshift is **past perfect**.","explanation":"A requested backshift from past simple uses **had + measured**.","keywords":["past-backshift"],"skill":"past-backshift","contextKey":"reported-statements-3","fingerprint":"3ed9bf98781abf98373cd870e8595bfb7ee160a58ef6445ff3fd6dfd3343607f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The original action is already past; the requested backshift is **past perfect**.","A requested backshift from past simple uses **had + measured**.","Choose **had measured**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had to changes the meaning to obligation rather than reporting the completed action.","B":"A requested backshift from past simple uses **had + measured**.","C":"Present perfect is not the requested backshift from past simple.","D":"Had needs a past participle in the past perfect."}}},{"id":"f88a2b9c-a529-51a2-a2c9-0be953a68400","topicSlug":"reported-statements","level":"B1","prompt":"Backshift this report: She said, “I translate the travel leaflet every week.” → She said she ____ the travel leaflet every week.","choices":[{"id":"A","text":"translates"},{"id":"B","text":"translating"},{"id":"C","text":"to translate"},{"id":"D","text":"translated"}],"answerId":"D","hint":"The reporting verb is past and the instruction requests a **present-to-past backshift**.","explanation":"The instruction requests backshift from present translate to past **translated**.","keywords":["present-backshift"],"skill":"present-backshift","contextKey":"reported-statements-4","fingerprint":"bf0c7d21c9c5100be5995710d6beb89be11130451ba34b994145183776b83d7c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb is past and the instruction requests a **present-to-past backshift**.","The instruction requests backshift from present translate to past **translated**.","Choose **translated**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This keeps present tense; the task explicitly requests backshift.","B":"An -ing form alone does not supply a finite reported verb.","C":"A to-infinitive does not complete this that-clause.","D":"The instruction requests backshift from present translate to past **translated**."}}},{"id":"676f790a-ffdb-5d3c-a460-241ce2ef4923","topicSlug":"reported-statements","level":"B1","prompt":"Report the plan with backshift: “I will translate the travel leaflet.” → She said she ____ the travel leaflet.","choices":[{"id":"A","text":"would translated"},{"id":"B","text":"would to translate"},{"id":"C","text":"will translating"},{"id":"D","text":"would translate"}],"answerId":"D","hint":"Backshift the **modal**, not the main verb after it.","explanation":"Backshift **will** to **would**, keeping base translate.","keywords":["future-backshift"],"skill":"future-backshift","contextKey":"reported-statements-4","fingerprint":"6a9c9ce3174caf5486c850e83acd1a9eec6fd56f7436be5a6bc9fa8465b0de35","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reported-statements"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Backshift the **modal**, not the main verb after it.","Backshift **will** to **would**, keeping base translate.","Choose **would translate**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The verb after would must remain in its base form.","B":"Would takes a bare infinitive without to.","C":"Will cannot